pattern:
echo "=== 1) есть ли строка в базе/хранилище opencode (это opencode-id или нет) ===" timeout 60 grep -rIl 'buxrrn8Mou2VJH' ~/.local/share/opencode/storage ~/.local/share/opencode/tool-output ~/.local/share/opencode/snapshot 2>/dev/null head python3 - <<'PY'
import sqlite3,os
db=os.path.expanduser("~/.local/share/opencode/opencode.db")
try:
    c=sqlite3.connect(f"file:{db}?mode=ro",uri=True)
    tabs=[r[0] for r in c.execute("select name from sqlite_master where type='table'")]
    print("  таблицы БД:", tabs[:20])
    found=False
    for t in tabs:
        try:
            cols=[d[1] for d in c.execute(f"pragma table_info('{t}')")]
            for col in cols:
                try:
                    if c.execute(f"select 1 from '{t}' where cast(\"{col}\" as text) like '%buxrrn8Mou2VJH%' limit 1").fetchone():
                        print(f"  НАЙДЕНО в {t}.{col}"); found=True
                except Exception: pass
        except Exception: pass
    if not found: print("  в БД opencode строки нет")
    c.close()
except Exception as e:
    print("  err", e)
PY echo echo "=== 2) ставит ли opencode заголовок окна/терминала ===" ls -1 ~/.local/share/opencode/bin/* 2>/dev/null head -1 echo "binary: $BIN" timeout 60 strings -n 6 "$BIN" grep -iE 'setWindowTitle|\\x1b\]0;|set-title|OSC.*title' head -5 echo echo "=== 3) заголовки видимых окон сейчас (есть ли шаблон '<id> — <app>') ===" DISPLAY=:0 bash -c 'for w in $(xdotool search --onlyvisible --name "" 2>/dev/null); do t=$(xprop -id $w WM_NAME 2>/dev/null | sed "s/.*= //"); case "$t" in *"—"*|*" - "*|*" – "*) echo "$t";; esac; done' 2>/dev/null sort -u head -20
